import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_CPP_SRC = r"""
#include <torch/extension.h>
torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps);
"""

_CUDA_SRC = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>
#include <cooperative_groups.h>
namespace cg = cooperative_groups;
// Split each normalized row across a few cooperative blocks so the kernel
// uses more than one SM when rows is small but n is very large.
__global__ void layernorm_fused_kernel(
    const float* __restrict__ x,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ y,
    const int64_t n,
    const int64_t rows,
    const int64_t units,
    const float eps,
    const bool vec,
    float* __restrict__ partials,
    const int chunks,
    const int64_t chunk_units) {
  // L2-aware row-group staging: process rows in waves whose activations
  // fit in L2, so the normalize pass re-reads x from cache instead of DRAM.
  // y is stored with a streaming hint so it does not evict the staged x.
  cg::grid_group grid = cg::this_grid();
  const int group_rows = gridDim.x;
  const int chunk = blockIdx.y;
  const int64_t waves = (rows + group_rows - 1) / group_rows;
  for (int64_t wave = 0; wave < waves; ++wave) {
    const int64_t row = wave * group_rows + blockIdx.x;
    const bool active = row < rows;
    int64_t base = 0;
    int64_t begin = 0;
    int64_t end = 0;
    if (active) {
      base = row * n;
      begin = static_cast<int64_t>(chunk) * chunk_units;
      end = begin + chunk_units;
      if (end > units) end = units;
      float local_sum = 0.0f;
      float local_sq = 0.0f;
      if (vec) {
        const float4* x4 = reinterpret_cast<const float4*>(x + base);
        const int64_t step = static_cast<int64_t>(blockDim.x) * 2;
        for (int64_t i = begin + threadIdx.x; i < end; i += step) {
          const int64_t j = i + static_cast<int64_t>(blockDim.x);
          const float4 a = x4[i];
          local_sum += a.x + a.y + a.z + a.w;
          local_sq += a.x * a.x + a.y * a.y + a.z * a.z + a.w * a.w;
          if (j < end) {
            const float4 b = x4[j];
            local_sum += b.x + b.y + b.z + b.w;
            local_sq += b.x * b.x + b.y * b.y + b.z * b.z + b.w * b.w;
          }
        }
      } else {
        const float* xr = x + base;
        for (int64_t i = begin + threadIdx.x; i < end; i += blockDim.x) {
          const float v = xr[i];
          local_sum += v;
          local_sq += v * v;
        }
      }
      __shared__ float s_sum[256];
      __shared__ float s_sq[256];
      s_sum[threadIdx.x] = local_sum;
      s_sq[threadIdx.x] = local_sq;
      __syncthreads();
      for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
        if (threadIdx.x < s) {
          s_sum[threadIdx.x] += s_sum[threadIdx.x + s];
          s_sq[threadIdx.x] += s_sq[threadIdx.x + s];
        }
        __syncthreads();
      }
      if (threadIdx.x == 0) {
        const int64_t p = (row * chunks + chunk) * 2;
        partials[p] = s_sum[0];
        partials[p + 1] = s_sq[0];
        __threadfence();
      }
    }
    grid.sync();
    if (active) {
      float total_sum = 0.0f;
      float total_sq = 0.0f;
      for (int c = 0; c < chunks; ++c) {
        const int64_t p = (row * chunks + c) * 2;
        total_sum += partials[p];
        total_sq += partials[p + 1];
      }
      const float mean = total_sum / static_cast<float>(n);
      float var = total_sq / static_cast<float>(n) - mean * mean;
      var = fmaxf(var, 0.0f);
      const float rstd = rsqrtf(var + eps);
      if (vec) {
        const float4* x4 = reinterpret_cast<const float4*>(x + base);
        const float4* w4 = reinterpret_cast<const float4*>(weight);
        const float4* b4 = reinterpret_cast<const float4*>(bias);
        float4* y4 = reinterpret_cast<float4*>(y + base);
        const int64_t step = static_cast<int64_t>(blockDim.x) * 2;
        const int64_t rstart = end - 1 - static_cast<int64_t>(threadIdx.x);
        for (int64_t i = rstart; i >= begin; i -= step) {
          const int64_t j = i - static_cast<int64_t>(blockDim.x);
          const float4 xv0 = x4[i];
          const float4 wv0 = w4[i];
          const float4 bv0 = b4[i];
          float4 out0;
          out0.x = (xv0.x - mean) * rstd * wv0.x + bv0.x;
          out0.y = (xv0.y - mean) * rstd * wv0.y + bv0.y;
          out0.z = (xv0.z - mean) * rstd * wv0.z + bv0.z;
          out0.w = (xv0.w - mean) * rstd * wv0.w + bv0.w;
          __stcs(y4 + i, out0);
          if (j >= begin) {
            const float4 xv1 = x4[j];
            const float4 wv1 = w4[j];
            const float4 bv1 = b4[j];
            float4 out1;
            out1.x = (xv1.x - mean) * rstd * wv1.x + bv1.x;
            out1.y = (xv1.y - mean) * rstd * wv1.y + bv1.y;
            out1.z = (xv1.z - mean) * rstd * wv1.z + bv1.z;
            out1.w = (xv1.w - mean) * rstd * wv1.w + bv1.w;
            __stcs(y4 + j, out1);
          }
        }
      } else {
        const int64_t rstart = end - 1 - static_cast<int64_t>(threadIdx.x);
        for (int64_t i = rstart; i >= begin; i -= blockDim.x) {
          __stcs(y + base + i, (x[base + i] - mean) * rstd * weight[i] + bias[i]);
        }
      }
    }
  }
}
torch::Tensor layernorm_forward(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, double eps) {
  TORCH_CHECK(x.is_cuda());
  TORCH_CHECK(weight.is_cuda() && bias.is_cuda());
  TORCH_CHECK(x.scalar_type() == at::kFloat);
  TORCH_CHECK(weight.scalar_type() == at::kFloat && bias.scalar_type() == at::kFloat);
  TORCH_CHECK(x.is_contiguous());
  TORCH_CHECK(weight.is_contiguous() && bias.is_contiguous());
  const int64_t n = weight.numel();
  TORCH_CHECK(bias.numel() == n);
  TORCH_CHECK(x.numel() % n == 0);
  const int64_t rows = x.numel() / n;
  auto y = at::empty_like(x);
  if (rows == 0 || n == 0) return y;
  const int threads = 256;
  const bool vec = ((n & 3) == 0);
  const int64_t units = vec ? (n >> 2) : n;
  // Occupancy-driven chunking: cooperative launches require all blocks to be
  // co-resident, so size the grid to fill every SM at maximum occupancy.
  // L2-aware row grouping: process rows in waves whose activations fit in
  // half of L2, so the second (normalize) pass reads x from cache instead
  // of DRAM, cutting global memory traffic for this memory-bound kernel.
  int max_blocks_per_sm = 0;
  cudaOccupancyMaxActiveBlocksPerMultiprocessor(
      &max_blocks_per_sm,
      layernorm_fused_kernel,
      threads,
      0);
  if (max_blocks_per_sm < 1) max_blocks_per_sm = 1;
  auto props = at::cuda::getCurrentDeviceProperties();
  const int num_sms = props->multiProcessorCount;
  const int64_t max_coop_blocks = static_cast<int64_t>(max_blocks_per_sm) * num_sms;
  const int64_t l2_bytes = static_cast<int64_t>(props->l2CacheSize);
  const int64_t row_bytes = n * static_cast<int64_t>(sizeof(float));
  const int64_t group_budget = l2_bytes > 0 ? (l2_bytes >> 1) : (int64_t)(8 * 1024 * 1024);
  int64_t group_rows = group_budget / row_bytes;
  if (group_rows < 1) group_rows = 1;
  if (group_rows > rows) group_rows = rows;
  if (group_rows > max_coop_blocks) group_rows = max_coop_blocks;
  int64_t chunks64 = max_coop_blocks / group_rows;
  if (chunks64 < 1) chunks64 = 1;
  if (chunks64 > units) chunks64 = units;
  const int chunks = static_cast<int>(chunks64);
  const int64_t chunk_units = (units + chunks - 1) / chunks;
  auto partials = at::empty({rows, chunks, 2}, x.options());
  const dim3 blocks(static_cast<unsigned int>(group_rows), static_cast<unsigned int>(chunks));
  auto stream = at::cuda::getCurrentCUDAStream();
  const float* x_ptr = x.data_ptr<float>();
  const float* w_ptr = weight.data_ptr<float>();
  const float* b_ptr = bias.data_ptr<float>();
  float* y_ptr = y.data_ptr<float>();
  float* p_ptr = partials.data_ptr<float>();
  float eps_f = static_cast<float>(eps);
  bool vec_f = vec;
  int chunks_f = chunks;
  int64_t n_f = n;
  int64_t rows_f = rows;
  int64_t units_f = units;
  int64_t chunk_units_f = chunk_units;
  void* args[] = {
      &x_ptr,
      &w_ptr,
      &b_ptr,
      &y_ptr,
      &n_f,
      &rows_f,
      &units_f,
      &eps_f,
      &vec_f,
      &p_ptr,
      &chunks_f,
      &chunk_units_f};
  cudaError_t status = cudaLaunchCooperativeKernel(
      reinterpret_cast<void*>(&layernorm_fused_kernel),
      blocks,
      threads,
      args,
      0,
      stream.stream());
  TORCH_CHECK(status == cudaSuccess);
  C10_CUDA_KERNEL_LAUNCH_CHECK();
  return y;
}
"""

_ext = load_inline(
    name="custom_layernorm_ext",
    cpp_sources=[_CPP_SRC],
    cuda_sources=[_CUDA_SRC],
    functions=["layernorm_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    LayerNorm implemented with a single custom CUDA kernel.
    """

    def __init__(self, normalized_shape: tuple):
        super().__init__()
        if isinstance(normalized_shape, int):
            normalized_shape = (normalized_shape,)
        self.normalized_shape = tuple(normalized_shape)
        self.eps = 1e-5
        self.weight = nn.Parameter(torch.ones(self.normalized_shape, dtype=torch.float32))
        self.bias = nn.Parameter(torch.zeros(self.normalized_shape, dtype=torch.float32))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if not x.is_cuda:
            x = x.cuda()
        x = x.contiguous().float()
        weight = self.weight.to(device=x.device, dtype=torch.float32).contiguous()
        bias = self.bias.to(device=x.device, dtype=torch.float32).contiguous()
        return _ext.layernorm_forward(x, weight, bias, self.eps)

